"""Build a dependency-free, offline scenario selector from the authored mapping."""
from pathlib import Path
import json,re
HERE=Path(__file__).resolve().parent
doc=json.loads((HERE/'scenario-map.json').read_text())
style=re.search(r'<style>(.*?)</style>',(HERE.parent/'biology-visual-review/review.html').read_text(),re.S).group(1)
page='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Hackathon task scenarios for Swarm Lab questions</title><style>__STYLE__ .option{border-left:3px solid #8bd4bc;padding:4px 14px;margin:18px 0}.option h3{font-size:1.1rem;margin:6px 0}.scope{font-size:.8rem;color:#ddc58d}.summary{max-width:1000px}.controls{grid-template-columns:2fr 1fr 1fr 1fr}@media(max-width:700px){.controls{grid-template-columns:1fr 1fr}}@media(max-width:450px){.controls{grid-template-columns:1fr}}</style>
<header><div class="eyebrow">Swarm Lab · task selection</div><h1>Which task actually tests the question?</h1><p class="summary">One to three ranked scenarios for every current candidate, plus the original briefs and proposed extensions. Exact mechanism and checkable outcomes come before an impressive demo.</p><div class="notice">Proposed designs, not implemented environments or experiment results. Start with API selection, shared-result repair or research curation for the LLM track. Physical and model-training questions keep their own testbeds.</div><div class="stats"><div class="stat"><b>214</b>atlas questions</div><div class="stat"><b>301</b>linked records</div><div class="stat"><b>19</b>reusable task kits</div><div class="stat"><b>1–3</b>options per item</div></div><nav class="nav"><a href="README.md">Top three and build order</a><a href="scenario-kits.md">Task contracts and scoring</a><a href="ranked-map.md">Complete written map</a><a href="workload-evidence.md">Workload evidence</a><a href="scenario-map.json">Structured mappings</a></nav></header>
<main><section class="controls" aria-label="Mapping filters"><label>Search question, ID or original project<input id="search" type="search" placeholder="e.g. SOC-07, immune, budget"></label><label>Record type<select id="kind"><option value="">All types</option></select></label><label>Ranked scenario<select id="scenario"><option value="">Any scenario</option></select></label><label>Task fit<select id="fit"><option value="">All fit categories</option></select></label></section><div class="toolbar"><span id="count" role="status" aria-live="polite"></span><button id="reset">Clear filters</button></div><div class="cards" id="cards"></div><noscript>Read the <a href="ranked-map.md">complete written map</a> without JavaScript.</noscript></main><footer>Snapshot 2026-10-03 · No registered hypotheses · Rankings are within each question, not measured effect sizes.</footer>
<script id="map-data" type="application/json">__DATA__</script><script>
'use strict';const data=JSON.parse(document.getElementById('map-data').textContent), get=id=>document.getElementById(id);const keys=['search','kind','scenario','fit'];let focusId=null;
function el(tag,text,cls){const x=document.createElement(tag);if(text!==undefined)x.textContent=text;if(cls)x.className=cls;return x;}
function a(text,url){const x=el('a',text);x.href=url;return x;}
function p(root,label,text){if(!text)return;const x=el('p');x.append(el('strong',label+' '),document.createTextNode(text));root.append(x);}
function option(id,value,label){const x=el('option',label);x.value=value;get(id).append(x);}
for(const k of Object.keys(data.metadata.counts))option('kind',k,k);for(const [id,s]of Object.entries(data.scenarios))option('scenario',id,s.title);for(const fit of new Set(data.mappings.map(x=>x.fit)))option('fit',fit,fit);
const base='https://github.com/dmarzzz/swarm-lab/blob/'+data.metadata.source_commit+'/';
function card(r){const c=el('article',undefined,'card');c.id=r.id;const b=el('div',undefined,'badges');b.append(el('span',r.id,'badge'),el('span',r.kind,'badge'));c.append(b,el('h2',r.title));p(c,'Fit:',r.fit);if(r.original_question)p(c,'Question:',r.original_question);for(const pick of r.ranked_scenarios){const s=data.scenarios[pick.scenario];const box=el('section',undefined,'option');box.append(el('h3',pick.rank+'. '+s.title),el('div','Scope: '+s.scope,'scope'),el('p',pick.candidate_specific_use));const d=el('details');d.append(el('summary','Scoring, minimum scope and risks'));p(d,'Task:',s.task);p(d,'Minimum fixture:',s.minimum_fixture);p(d,'Score:',s.scoring);p(d,'Compare with:',s.baseline);p(d,'Cut:',s.scope_cut);p(d,'Risk:',s.interpretation_risk);box.append(d);c.append(box);}const d=el('details');d.append(el('summary','Keep the original research contrast'));p(d,'Original comparison:',r.original_comparison);p(d,'Confounds:',r.original_confounds);p(d,'Falsifier:',r.original_falsifier);p(d,'Metrics:',r.original_metrics.join('; '));p(d,'Original briefs:',r.briefs.join(', '));p(d,'Related:',r.related.join(', '));c.append(d);const links=el('div',undefined,'links');links.append(a('Original source',base+r.path),a('Permalink','#'+r.id));c.append(links);return c;}
function render(){const q=get('search').value.trim().toLowerCase();const found=data.mappings.filter(r=>(!focusId||r.id===focusId)&&(!q||JSON.stringify(r).toLowerCase().includes(q))&&(!get('kind').value||r.kind===get('kind').value)&&(!get('fit').value||r.fit===get('fit').value)&&(!get('scenario').value||r.ranked_scenarios.some(p=>p.scenario===get('scenario').value)));get('count').textContent=found.length+' of '+data.mappings.length+' records';const f=document.createDocumentFragment();for(const r of found)f.append(card(r));if(!found.length)f.append(el('p','No matching records. Clear a filter or try another term.','empty'));get('cards').replaceChildren(f);}
for(const id of keys)get(id).addEventListener(id==='search'?'input':'change',()=>{focusId=null;render();});get('reset').onclick=()=>{focusId=null;for(const k of keys)get(k).value='';history.replaceState(null,'',location.pathname);render();};function deep(){const id=decodeURIComponent(location.hash.slice(1));if(!data.mappings.some(r=>r.id===id))return;focusId=id;for(const k of keys)get(k).value='';get('search').value=id;render();get(id)?.scrollIntoView({block:'start'});}render();deep();window.addEventListener('hashchange',deep);
</script></html>'''
page=page.replace('__STYLE__',style).replace('__DATA__',json.dumps(doc,ensure_ascii=False).replace('<','\\u003c'))
(HERE/'review.html').write_text(page)
print('Rendered',len(doc['mappings']),'ranked records')
